import{_ as t,o,c as d,a2 as a}from"./chunks/framework.hwbV7reR.js";const k=JSON.parse('{"title":"Входящий API","description":"","frontmatter":{},"headers":[],"relativePath":"api.md","filePath":"api.md","lastUpdated":1791695486000}'),c={name:"api.md"};function i(n,e,s,r,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="входящии-api" tabindex="-1">Входящий API <a class="header-anchor" href="#входящии-api" aria-label="Permalink to &quot;Входящий API&quot;">​</a></h1><p>API предназначен для доверенного backend, после проверки пользователя и права на подключение. Все маршруты, включая health, требуют <code>Authorization: Bearer &lt;token&gt;</code>. Backend-токен берётся из отдельного файла на сервере. Управление узлами доступно локальному CLI и отдельной панели с <code>--manage</code>; <code>/internal/admin/*</code> больше не обслуживается. Внешний доступ — только через HTTPS и ограничение источников; локально сервис слушает <code>127.0.0.1:8792</code>. Все ответы имеют <code>Cache-Control: private, no-store</code>; тела и заголовки авторизации не должны попадать в журналы reverse proxy и трассировки.</p><p>Самостоятельная <a href="./panel.html">панель просмотра</a> использует другой порт и собственный ключ; её <code>/admin/v1/overview</code> не является маршрутом этого backend API.</p><p>Машиночитаемые модели: <a href="https://github.com/UndercoreCo/orchestrator/blob/main/contracts/orchestrator-connections.schema.json" target="_blank" rel="noreferrer">JSON Schema</a>. Версия URL <code>/internal/v2</code> и <code>schema_version: 1</code> — разные уровни версионирования. <code>GET /internal/v2/capabilities</code> показывает реально включённые возможности.</p><p>Полный пример: <a href="./integration.html">интеграция backend</a>. Статическая <a href="https://github.com/UndercoreCo/orchestrator/blob/main/contracts/openapi.json" target="_blank" rel="noreferrer">OpenAPI 3.1</a> описывает v2, health и обзор узлов; совместимые операции v1 остаются в этом руководстве. <a href="./errors.html">Обработка ошибок</a>.</p><h2 id="операции" tabindex="-1">Операции <a class="header-anchor" href="#операции" aria-label="Permalink to &quot;Операции&quot;">​</a></h2><p><code>{id}</code> — стабильный <code>connection_id</code>, возвращённый сервисом.</p><table tabindex="0"><thead><tr><th>Метод и путь</th><th>Назначение / тело</th></tr></thead><tbody><tr><td><code>GET /v1/health</code></td><td>Состояние процесса и версия релиза; не проверка всех узлов</td></tr><tr><td><code>GET /internal/v1/metrics</code></td><td>Метрики Prometheus и очередь из локального журнала, без запросов к агентам</td></tr><tr><td><code>GET /internal/v1/nodes</code></td><td>Узлы, режимы, число назначений; не актуальный speed test</td></tr><tr><td><code>POST /internal/v2/connections</code></td><td>Создать или получить назначение: <code>DeviceRequest</code></td></tr><tr><td><code>GET /internal/v2/connections/{id}?device_id=…</code></td><td>Состояние принадлежащего устройству подключения</td></tr><tr><td><code>POST /internal/v2/connections/{id}/export</code></td><td>Файл или готовый QR: <code>ExportRequest</code></td></tr><tr><td><code>POST /internal/v2/connections/{id}/configuration</code></td><td>Получить параметры: <code>ConfigurationRequest</code></td></tr><tr><td><code>POST /internal/v2/connections/{id}/renew</code></td><td>Продлить: <code>device_id</code>, <code>expires_at</code>, <code>idempotency_key</code></td></tr><tr><td><code>POST /internal/v2/connections/{id}/disable</code></td><td>Отозвать: <code>device_id</code></td></tr><tr><td><code>POST /internal/v2/connections/{id}/enable</code></td><td>Включить ранее отключённое: <code>device_id</code>; срок доступа не продлевается</td></tr><tr><td><code>POST /internal/v2/connections/{id}/recover</code></td><td>Восстановить: <code>RecoveryRequest</code>, текущая <code>expected_revision</code></td></tr><tr><td><code>POST /internal/v2/connections/{id}/switch</code></td><td>Операторское переключение: <code>SwitchRequest</code>; не открывать клиентам напрямую</td></tr><tr><td><code>POST /internal/v2/connections/{id}/replace</code></td><td>Совместимость замены: <code>device_id</code>, <code>expected_external_id</code>, <code>expires_at</code>, <code>idempotency_key</code>, необязательный <code>allow_create</code></td></tr></tbody></table><p>Пример создания (синтетические значения):</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schema_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;device_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;device-example-01&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MacBook&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;expires_at&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2027-01-01T00:00:00.000Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;capabilities&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;protocol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;amneziawg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;configuration_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Создание возвращает <code>Connection</code>: идентификаторы подключения, устройства и узла, протокол, состояние и срок. Получение <code>/configuration</code> требует тех же <code>schema_version</code>, <code>device_id</code>, <code>capabilities</code>, без имени и срока. Ответ дополнительно содержит <code>revision</code> и <code>configuration</code> с <code>protocol</code>, <code>version</code>, <code>format</code>, <code>data</code>. <code>data</code> содержит секретный документ для VPN-движка. Не логировать его и не помещать в URL, аналитику, диагностический экспорт или открытый кэш.</p><h2 id="повторы-и-восстановление" tabindex="-1">Повторы и восстановление <a class="header-anchor" href="#повторы-и-восстановление" aria-label="Permalink to &quot;Повторы и восстановление&quot;">​</a></h2><p>Повтор создания одного устройства с совместимым протоколом использует прежнее назначение. Продление и переключение имеют ключ идемпотентности. При сетевом таймауте повторять тот же запрос и ключ, не создавать новое устройство.</p><p><code>recover</code> использует ревизию, которую получил клиент. Повтор старой ревизии не переключает устройство обратно. Между новыми переключениями действует ограничение 1800 секунд. Изменение узла сохраняет <code>connection_id</code> и <code>device_id</code>.</p><p>Если отзыв старого доступа ещё не подтверждён, переключение не считается завершённым. Фоновый обработчик продолжает незавершённые операции. Для узла с подтверждённым коротким разрешением полный отказ API переводит операцию в ожидание <code>503 lease_waiting</code>. Разрешение больше не продлевается; после безопасного интервала операция продолжается в фоне или при повторе той же revision. Узлы без leases по-прежнему требуют подтверждённого отзыва через API. Перезагрузка управляющей машины начинает безопасное ожидание заново.</p><h2 id="ошибки" tabindex="-1">Ошибки <a class="header-anchor" href="#ошибки" aria-label="Permalink to &quot;Ошибки&quot;">​</a></h2><p>Тело прикладной ошибки: <code>{&quot;detail&quot;:&quot;machine_readable_code&quot;}</code>. Примеры:</p><table tabindex="0"><thead><tr><th>HTTP</th><th>Смысл</th></tr></thead><tbody><tr><td>401</td><td>Нет действительного служебного токена</td></tr><tr><td>404</td><td>Подключение не найдено/не принадлежит указанному устройству</td></tr><tr><td>409</td><td>Конфликт состояния, ревизии, идемпотентности или требуется обновление клиента</td></tr><tr><td>410</td><td>Доступ истёк/недоступен в запрошенной операции</td></tr><tr><td>413 / 422</td><td>Слишком большой или неверный запрос</td></tr><tr><td>429</td><td>Пауза между восстановлениями, <code>recovery_cooldown</code></td></tr><tr><td>503</td><td>Нет подходящего узла, узел недоступен или идентичность не подтверждена</td></tr></tbody></table><p>Точный код зависит от операции. Нельзя трактовать любой 503 как доказательство блокировки провайдером или повторять мутацию с новым ключом без проверки состояния.</p><h2 id="совместимость-v1" tabindex="-1">Совместимость v1 <a class="header-anchor" href="#совместимость-v1" aria-label="Permalink to &quot;Совместимость v1&quot;">​</a></h2><p>Сохранены <code>/v1/clients</code>, <code>/v1/clients/{id}</code> и операции <code>configuration</code>, <code>amnezia</code>, <code>renew</code>, <code>replace</code>, <code>enable</code>, <code>disable</code> для существующего backend. Новый код должен использовать контракт v2. Поле <code>mode: pilot</code> в старом health сохранено ради совместимости и не определяет способ развёртывания.</p><h2 id="локальное-управление-узлами" tabindex="-1">Локальное управление узлами <a class="header-anchor" href="#локальное-управление-узлами" aria-label="Permalink to &quot;Локальное управление узлами&quot;">​</a></h2><p>Административные HTTP-маршруты удалены. Backend заказчика не имеет ключа управления оркестратором. Используйте <code>undercore-orchestrator add/update/check/restore server</code> и <code>list servers</code>, описанные в <a href="./quickstart.html">быстром старте</a>.</p><p>Полный каталог машинных ошибок: <code>contracts/errors.json</code>; CI проверяет наличие каждого кода в каталоге. Формат ошибок v1/v2 остаётся <code>{ &quot;detail&quot;: &quot;code&quot; }</code>. Новая асинхронная операция с ответом 202 и новая оболочка ошибок требуют отдельной версии контракта; в этом рефакторинге они намеренно не вводятся.</p><h2 id="точечныи-поиск-для-backend-v1" tabindex="-1">Точечный поиск для backend v1 <a class="header-anchor" href="#точечныи-поиск-для-backend-v1" aria-label="Permalink to &quot;Точечный поиск для backend v1&quot;">​</a></h2><p><code>POST /v1/clients/lookup</code> принимает только <code>external_id</code> (1–100 символов <code>A-Za-z0-9_-</code>) и <code>device_id: &quot;account-v1&quot;</code>. Требуются тот же служебный Bearer-токен и HTTPS; ответ имеет <code>Cache-Control: private, no-store</code>.</p><p>Ответ: <code>{&quot;clients&quot;: []}</code> либо <code>{&quot;clients&quot;: [client]}</code> с прежней моделью v1. Поиск использует уникальный индекс журнала назначений, не полный список клиентов. Если назначения нет, VPN-узлы не опрашиваются. Если оно есть, проверяется только закреплённый узел; выключенный доступ остаётся выключенным. Незавершённое создание после потери ответа восстанавливается на прежнем узле с той же identity. Таймаут, конфликт владельца/узла и 503 не превращаются в пустой результат. Подтверждённый 404 отсутствующего peer сохраняет прежнюю семантику поиска v1. Операция не создаёт назначение, не продлевает доступ и не выдаёт секретный документ.</p><p>Старый <code>GET /v1/clients</code> сохраняется для совместимости. Backend должен включать новый маршрут после обновления оркестратора. Автоматического fallback к полному списку при отказе нового маршрута нет.</p><h2 id="экспорт-для-сторонних-приложении-0-3-4" tabindex="-1">Экспорт для сторонних приложений (0.3.4) <a class="header-anchor" href="#экспорт-для-сторонних-приложении-0-3-4" aria-label="Permalink to &quot;Экспорт для сторонних приложений (0.3.4)&quot;">​</a></h2><p><code>POST /internal/v2/connections/{id}/export</code> получает <code>schema_version: 1</code>, <code>device_id</code>, <code>format</code> (<code>conf</code>, <code>amnezia-vpn</code> или <code>qr</code>). Доступные значения публикует адаптер в <code>GET /internal/v2/capabilities</code> → <code>protocols[].export_formats</code>. Оркестратор не выбирает другой протокол при неподдерживаемом формате.</p><p>AmneziaWG предоставляет <code>.conf</code>, <code>.vpn</code> (содержимое <code>vpn://</code>) и QR в PNG. По умолчанию QR кодирует <code>.conf</code> для AmneziaWG. Для AmneziaVPN передайте <code>format: &quot;qr&quot;, qr_content_format: &quot;amnezia-vpn&quot;</code>; для обычного файла эта опция не используется. Два QR не взаимозаменяемы: сканирующее приложение должно понимать выбранное представление.</p><p>Ответ <code>ConnectionExport</code> содержит идентификаторы, протокол, состояние, срок и <code>document</code>: <code>format</code>, <code>media_type</code>, <code>extension</code>, <code>encoding</code>, <code>data</code>. Файлы передаются как <code>utf-8</code>, готовый PNG — как <code>base64</code>. Backend проверяет принадлежность и срок, возвращает файл/картинку пользователю; не строит VPN-документ и не определяет его содержимое. Безопасное имя загрузки может задавать backend. Экспорт использует существующее назначение и не занимает дополнительный слот.</p><p>Проверяются владелец устройства, состояние peer, срок, запрет выдачи, lease и незавершённое переключение. Неверное устройство — 404, неподдерживаемый формат — 422 <code>unsupported_format</code>, неактивный доступ — 410 <code>access_unavailable</code>. Слишком большой для одного QR документ — 422 <code>qr_unavailable</code>, без обрезки. Предел: 64 KiB файла, 2331 байт QR (byte mode, ECC M). Все данные остаются в памяти; в журнал, SQLite или URL не попадают. Ответы <code>private, no-store</code>.</p><p>Для WireGuard предусмотрена отдельная политика экспорта только <code>.conf</code> и QR; полноценного WireGuard-драйвера lifecycle пока нет, runtime его не рекламирует. TrustTunnel также не рекламируется. Добавление протокола требует рабочего драйвера и тестов lifecycle, а не только наличия форматтера.</p><p>Скачанный файл/QR — снимок параметров. В стороннем клиенте он не обновится сам при переносе подключения на другой узел: нужно повторно импортировать экспорт. Собственные клиенты продолжают использовать <code>/configuration</code> и recovery.</p><h2 id="корреляция-и-диагностика" tabindex="-1">Корреляция и диагностика <a class="header-anchor" href="#корреляция-и-диагностика" aria-label="Permalink to &quot;Корреляция и диагностика&quot;">​</a></h2><p>Ответы содержат сгенерированный сервером X-Request-ID; входной заголовок с этим именем не используется. Передайте идентификатор оператору при сбое, не пересылая секретный документ. Подробнее: <a href="./observability.html">диагностика и метрики</a>.</p><p>Локальная перегрузка возвращает <code>503 connection_busy</code>; общий бюджет операции — <code>503 node_unavailable</code>. Это не доказательство отказа VPN-узла. <a href="./runtime-limits.html">Лимиты и правила повторов</a>.</p>`,38)])])}const u=t(c,[["render",i]]);export{k as __pageData,u as default};
